return ['domain'=>'blockstudio','plural-forms'=>'nplurals=1; plural=0;','language'=>'ka_GE','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:31+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'%2$s ბლოკის ტეგზე ატრიბუტი „%1$s“ ამოღებულია, რადგან ბლოკში ამ ID-ის მქონე ველი არ არის გამოცხადებული. გამოაცხადეთ ეს ველი ან მიუთითეთ იგი როგორც data-, aria- ან html- ატრიბუტი, რათა ძირეულ ელემენტს დაემატოს.','This storage key is not declared by the block or its extensions.'=>'ეს შენახვის გასაღები ბლოკში ან მის გაფართოებებში გამოცხადებული არ არის.','This top-level key is not an attribute of the block, so it is ignored.'=>'ეს ზედა დონის გასაღები ბლოკის ატრიბუტი არ არის და ამიტომ უგულებელყოფილია.','This key is only read inside the blockstudio object, which is missing.'=>'ამ გასაღებს მხოლოდ blockstudio ობიექტის შიგნით კითხულობენ, რომელიც აკლია.','This value is not among the field options.'=>'ეს მნიშვნელობა ველის ვარიანტებს შორის არ არის.','This value has an unsupported shape for the field.'=>'ამ ველისთვის მნიშვნელობის ფორმა მხარდაჭერილი არ არის.','This repeater has fewer rows than its minimum.'=>'ამ გამეორებელში მინიმუმზე ნაკლები რიგია.','This repeater has more rows than its maximum.'=>'ამ გამეორებელში მაქსიმუმზე მეტი რიგია.','This storage key has conflicting field definitions.'=>'ამ შენახვის გასაღებისთვის ველების განსაზღვრებები ერთმანეთს ეწინააღმდეგება.','The nested field value overrides this top-level value.'=>'ჩადგმული ველის მნიშვნელობა ამ ზედა დონის მნიშვნელობას ანაცვლებს.','Extension bindings read this value only from blockstudio.attributes.'=>'გაფართოების მიბმები ამ მნიშვნელობას მხოლოდ blockstudio.attributes-იდან კითხულობს.','Blockstudio field values must be stored in an object.'=>'Blockstudio-ის ველების მნიშვნელობები ობიექტში უნდა ინახებოდეს.','Block